const buildGraph = (edges) => {
    const graph = {};

    for (const edge of edges) {
        const [nodeOne, nodeTwo] = edge;

        const nodeOneInGraph = graph.hasOwnProperty(nodeOne);
        const nodeTwoInGraph = graph.hasOwnProperty(nodeTwo);

        if (!nodeOneInGraph) graph[nodeOne] = [];
        if (!nodeTwoInGraph) graph[nodeTwo] = [];

        graph[nodeOne].push(nodeTwo);
        graph[nodeTwo].push(nodeOne);
    }

    return graph;
};

// CONTRACT for markComponentAsVisited(graph, node, visited):
//     when this call returns, `node` and every node reachable
//     from `node` is in the visited set.
const markComponentAsVisited = (graph, node, visited) => {
    // Base cases
    if (visited.has(node)) return;

    // Process node
    visited.add(node);

    // Add neighbors
    const nodeInGraph = graph.hasOwnProperty(node);
    if (!nodeInGraph) return;

    const neighbors = graph[node];

    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `neighbor` and everything
        // reachable from it is in visited. Trust it, do not trace it.
        // This function already put `node` into visited, and each
        // neighbor's contract puts everything reachable from that
        // neighbor into visited — together, that is this function's
        // full contract, kept.
        markComponentAsVisited(graph, neighbor, visited);
    }
};

const countComponents = (numNodes, edges) => {
    const graph = buildGraph(edges);

    let numConnectedComponents = 0;
    const visited = new Set();

    for (let node = 0; node < numNodes; node++) {
        if (visited.has(node)) continue;

        numConnectedComponents++;

        // The recursive leap of faith: trust the contract. When this
        // call returns, `node` and everything reachable from it — the
        // entire brand-new component — is in visited, so the loop can
        // never count this component again. We do not trace inside;
        // we just count it and move on.
        markComponentAsVisited(graph, node, visited);
    }

    return numConnectedComponents;
};

const CONNECTED = 1;

// CONTRACT for markProvinceAsVisited(visited, city, isConnected):
//     when this call returns, `city` and every city connected to it —
//     directly or through chains of connections — is in the visited
//     set.
const markProvinceAsVisited = (visited, city, isConnected) => {
    // For this problem, our base case in automatically handled
    // (our base case occurs when the current city has 0 unvisited
    // neighbor cities).

    // Process node
    visited.add(city);

    // Recurse on neighbors
    for (
        let potentialNeighborCity = 0;
        potentialNeighborCity < isConnected.length;
        potentialNeighborCity++
    ) {
        const isNeighbor =
            isConnected[city][potentialNeighborCity] === CONNECTED;

        if (!isNeighbor) continue;

        // This is an undirected graph. If we can go from city 0 to city 1,
        // then we can go from city 1 to city 0.
        // Thus, this graph CAN have cycles (all undirected graphs can have cycles),
        // so we must tracked visited nodes to prevent infinite loops.
        if (visited.has(potentialNeighborCity)) continue;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the neighbor city and
        // every city connected to it is in visited. Trust it, do not
        // trace it. This function already put `city` into visited, and
        // each neighbor's contract covers the rest of the province —
        // together, that is this function's full contract, kept.
        markProvinceAsVisited(visited, potentialNeighborCity, isConnected);
    }
};

const findCircleNum = (isConnected) => {
    const numCities = isConnected.length;

    let numProvinces = 0;
    const visited = new Set();

    for (let startCity = 0; startCity < numCities; startCity++) {
        if (visited.has(startCity)) continue;

        numProvinces++;

        // The recursive leap of faith: trust the contract. When this
        // call returns, every city in this newly found province is in
        // visited, so the loop can never count this province again. We
        // do not trace inside; we just count it and move on.
        markProvinceAsVisited(visited, startCity, isConnected);
    }

    return numProvinces;
};

const LAND = '1';

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (grid, row, col) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

// CONTRACT for markIslandAsVisited(grid, row, col, visited):
//     when this call returns, if the cell at `row`,`col` is land,
//     that cell and every land cell of the same island is in the
//     visited set. (Water or out-of-bounds cells change nothing.)
const markIslandAsVisited = (grid, row, col, visited) => {
    // Base case
    if (!isInBounds(grid, row, col)) return;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return;

    if (grid[row][col] !== LAND) return;

    // Process node
    visited.add(curPositionString);

    // Recurse on potential neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the neighbor cell (if
        // it is land) and every land cell connected to it is in
        // visited. Trust it, do not trace it. This function already
        // put `row`,`col` into visited, and each neighbor's contract
        // covers the rest of the island — together, that is this
        // function's full contract, kept.
        markIslandAsVisited(grid, newRow, newCol, visited);
    }
};

const numIslands = (grid) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    let numberOfIslands = 0;
    const visited = new Set();

    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            const curPositionString = getPositionString(row, col);

            if (visited.has(curPositionString)) continue;

            const terrainType = grid[row][col];
            if (terrainType !== LAND) continue;

            numberOfIslands++;

            // The recursive leap of faith: trust the contract. When this
            // call returns, every cell of this newly found island is in
            // visited, so the loops can never count the same island again.
            // We do not trace inside; we just count it and move on.
            markIslandAsVisited(grid, row, col, visited);
        }
    }

    return numberOfIslands;
};

const numberToLettersMap = {
    1: [],
