// CONTRACT for generateCombinations(digits, location, stringSoFar, allCombinations):
//     when this call returns, every full combination that begins with
//     `stringSoFar` and continues with one letter for each digit from
//     position `location` onward has been pushed onto
//     `allCombinations`.
const generateCombinations = (digits, location, stringSoFar, allCombinations) => {
    // Base case
    if (location === digits.length) {
        allCombinations.push(stringSoFar);
        return;
    }

    // Process node

    // Traverse neighbors
    const curDigit = digits[location];
    const chars = numberToLettersMap[curDigit];

    for (const char of chars) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, every combination that
        // begins with `stringSoFar` + `char` and covers the remaining
        // digits has been pushed. Trust it, do not trace it. Doing
        // this once for each letter of the current digit covers every
        // way to continue — exactly this function's contract, kept.
        generateCombinations(digits, location + 1, stringSoFar + char, allCombinations);
    }
};

const letterCombinations = (digits) => {
    if (digits.length === 0) return [];

    const allCombinations = [];

    // The recursive leap of faith: trust the contract. When this
    // call returns, allCombinations holds every string that picks
    // one letter per digit, from the first digit to the last. We
    // do not trace inside; we just return the finished list.
    generateCombinations(digits, 0, '', allCombinations);

    return allCombinations;
};

const START_NODE = 0;

// CONTRACT for getPathsFromNodeToTarget(graph, curNode, targetNode):
//     returns a list of every path from `curNode` to `targetNode`,
//     where each path is the list of nodes it visits, in order.
const getPathsFromNodeToTarget = (graph, curNode, targetNode) => {
    // Base cases
    if (curNode === targetNode) return [[curNode]];

    // Process node
    const allPathsFromNodeToTarget = [];

    // Recurse on neighbors
    const neighbors = graph[curNode];
    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — it returns every path from `neighbor` to
        // the target. Trust it, do not trace it. Sticking `curNode` on
        // the front of each neighbor's guaranteed paths, for every
        // neighbor, builds every path from `curNode` — exactly this
        // function's contract, kept.
        const pathsFromNeighborToTarget = getPathsFromNodeToTarget(
            graph,
            neighbor,
            targetNode,
        );

        for (const path of pathsFromNeighborToTarget) {
            const pathFromCurToTarget = [curNode, ...path];

            allPathsFromNodeToTarget.push(pathFromCurToTarget);
        }
    }

    return allPathsFromNodeToTarget;
};

const allPathsSourceTarget = (graph) => {
    const targetNode = graph.length - 1;

    // The recursive leap of faith: trust the contract. This call
    // returns every path from node 0 to the target node. We do not
    // trace inside; we just return that list.
    return getPathsFromNodeToTarget(graph, START_NODE, targetNode);
};
